  1→/**
  2→ * Triage API Routes
  3→ *
  4→ * REST endpoints for triage operations:
  5→ * - GET /api/triage - list records with filters and pagination
  6→ * - GET /api/triage/export - export records for agent handoff
  7→ * - POST /api/triage - record a triage decision
  8→ * - GET /api/triage/:ref - get single record
  9→ * - POST /api/triage/:ref/override - override a decision
 10→ * - POST /api/triage/:ref/act - execute a triage action
 11→ *
 12→ * AC Coverage:
 13→ * - @triage-daemon-api ac-1: GET list sorted by created_at desc
 14→ * - @triage-daemon-api ac-2: Status filter on GET list
 15→ * - @triage-daemon-api ac-3: POST creates record with snapshot
 16→ * - @triage-daemon-api ac-4: PUT override sets override fields
 17→ * - @triage-daemon-api ac-5: PUT act executes and transitions
 18→ * - @triage-daemon-api ac-6: GET export with format parameter
 19→ * - @triage-daemon-api ac-7: POST 404 for nonexistent inbox item
 20→ * - @triage-daemon-api ac-8: PUT act 409 for already acted
 21→ * - @triage-daemon-api ac-9: PUT act 422 for pending record
 22→ */
 23→
 24→import { Elysia, t } from 'elysia';
 25→import { ulid } from 'ulidx';
 26→import {
 27→  initContext,
 28→  loadTriageRecords,
 29→  saveTriageRecord,
 30→  findTriageRecordByRef,
 31→  findTriageRecordByInboxRef,
 32→  loadInboxItems,
 33→  findInboxItemByRef,
 34→  getAuthor,
 35→  type LoadedTriageRecord,
 36→} from '../../parser/index.js';
 37→import { commitIfShadow } from '../../parser/shadow.js';
 38→import { normalizeRefInput } from '../../schema/index.js';
 39→import type { TriageAction } from '../../schema/index.js';
 40→import { exportTriageRecords } from '../../export/triage.js';
 41→import { executeTriageAction, VALID_ACTIONS } from '../../triage/index.js';
 42→import type { PubSubManager } from '../websocket/pubsub';
 43→
 44→interface TriageRouteOptions {
 45→  pubsub: PubSubManager;
 46→}
 47→
 48→// VALID_ACTIONS and executeTriageAction imported from shared triage module
 49→
 50→export function createTriageRoutes(options: TriageRouteOptions) {
 51→  const { pubsub } = options;
 52→
 53→  return new Elysia({ prefix: '/api/triage' })
 54→    // AC: @triage-daemon-api ac-1, ac-2 - List triage records with filters and pagination
 55→    // AC: @trait-api-endpoint ac-1, ac-4 - JSON response with pagination wrapper
 56→    .get(
 57→      '/',
 58→      async ({ query, projectContext }) => {
 59→        // AC: @multi-directory-daemon ac-1, ac-24 - Use project context from middleware
 60→        const ctx = await initContext(projectContext.path);
 61→        const records = await loadTriageRecords(ctx);
 62→
 63→        // Apply filters
 64→        let filtered = records;
 65→
 66→        // AC: @triage-daemon-api ac-2 - Status filter
 67→        if (query.status) {
 68→          const statusFilters = Array.isArray(query.status) ? query.status : [query.status];
 69→          filtered = filtered.filter((r) => statusFilters.includes(r.status));
 70→        }
 71→
 72→        // Action filter
 73→        if (query.action) {
 74→          const actionFilters = Array.isArray(query.action) ? query.action : [query.action];
 75→          filtered = filtered.filter((r) => r.action && actionFilters.includes(r.action));
 76→        }
 77→
 78→        // AC: @triage-daemon-api ac-1 - Sort by created_at descending (newest first)
 79→        filtered.sort(
 80→          (a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime()
 81→        );
 82→
 83→        // AC: @trait-api-endpoint ac-4 - Pagination with limit and offset
 84→        const total = filtered.length;
 85→        const offset = Number(query.offset) || 0;
 86→        const limit = Number(query.limit) || total;
 87→
 88→        const paginated = filtered.slice(offset, offset + limit);
 89→
 90→        return {
 91→          items: paginated,
 92→          total,
 93→          offset,
 94→          limit,
 95→        };
 96→      },
 97→      {
 98→        query: t.Object({
 99→          status: t.Optional(t.Union([t.String(), t.Array(t.String())])),
100→          action: t.Optional(t.Union([t.String(), t.Array(t.String())])),
101→          limit: t.Optional(t.String()),
102→          offset: t.Optional(t.String()),
103→        }),
104→      }
105→    )
106→
107→    // AC: @triage-daemon-api ac-6 - Export triage records
108→    // NOTE: This route MUST be defined before /:ref to avoid "export" being parsed as a ref
109→    .get(
110→      '/export',
111→      async ({ query, projectContext }) => {
112→        // AC: @multi-directory-daemon ac-1, ac-24 - Use project context from middleware
113→        const ctx = await initContext(projectContext.path);
114→        let records = await loadTriageRecords(ctx);
115→
116→        // Optional status filter on export
117→        if (query.status) {
118→          const statusFilters = Array.isArray(query.status) ? query.status : [query.status];
119→          records = records.filter((r) => statusFilters.includes(r.status));
120→        }
121→
122→        const format = (query.format || 'json') as 'json' | 'context';
123→
124→        // AC: @triage-daemon-api ac-6 - Export via shared formatter
125→        // AC: @triage-agent-export ac-1, ac-2, ac-3, ac-4
126→        return exportTriageRecords(records, format);
127→      },
128→      {
129→        query: t.Object({
130→          format: t.Optional(t.String()),
131→          status: t.Optional(t.Union([t.String(), t.Array(t.String())])),
132→        }),
133→      }
134→    )
135→
136→    // AC: @triage-daemon-api ac-3 - Record a triage decision
137→    // AC: @trait-api-endpoint ac-1, ac-3, ac-5 - JSON response, validation, shadow commit
138→    .post(
139→      '/',
140→      async ({ body, error: errorResponse, projectContext }) => {
141→        // AC: @multi-directory-daemon ac-1, ac-24 - Use project context from middleware
142→        const ctx = await initContext(projectContext.path);
143→
144→        // AC: @trait-api-endpoint ac-3 - Validate action
145→        if (!VALID_ACTIONS.includes(body.action)) {
146→          return errorResponse(400, {
147→            error: 'validation_error',
148→            details: [
149→              {
150→                field: 'action',
151→                message: `Action must be one of: ${VALID_ACTIONS.join(', ')}`,
152→              },
153→            ],
154→          });
155→        }
156→
157→        // AC: @triage-daemon-api ac-7 - Validate inbox item exists
158→        const inboxItems = await loadInboxItems(ctx);
159→        const inboxItem = findInboxItemByRef(inboxItems, body.inbox_ref);
160→        if (!inboxItem) {
161→          // AC: @trait-api-endpoint ac-2 - 404 with error guidance
162→          return errorResponse(404, {
