165→            suggestion: 'Use kspec inbox list or GET /api/inbox to find valid inbox item references',
166→          });
167→        }
168→
169→        const author = body.decided_by || getAuthor(ctx.config?.identity?.author);
170→        const evidenceRefs = body.evidence_refs
171→          ? body.evidence_refs.map(normalizeRefInput)
172→          : [];
173→
174→        // Check if a record already exists for this inbox item (upsert case)
175→        const existingRecords = await loadTriageRecords(ctx);
176→        const existing = findTriageRecordByInboxRef(existingRecords, inboxItem._ulid);
177→
178→        // AC: @triage-daemon-api ac-3 - Create record with item_snapshot
179→        const record: LoadedTriageRecord = {
180→          _ulid: existing?._ulid || ulid(),
181→          inbox_ref: inboxItem._ulid,
182→          item_snapshot: inboxItem.text,
183→          status: 'triaged',
184→          action: body.action as TriageAction,
