188→          created_at: existing?.created_at || new Date().toISOString(),
189→        };
190→
191→        await saveTriageRecord(ctx, record);
192→
193→        // Reload to get the persisted record (saveTriageRecord may upsert by inbox_ref)
194→        const savedRecords = await loadTriageRecords(ctx);
195→        const savedRecord = findTriageRecordByInboxRef(savedRecords, inboxItem._ulid) || record;
196→
197→        // AC: @trait-api-endpoint ac-5 - Shadow commit
198→        await commitIfShadow(ctx.shadow, `triage: record ${savedRecord._ulid.slice(0, 8)} as ${savedRecord.action}`);
199→
200→        // AC: @triage-daemon-api ac-3 - Broadcast triage:updates via WebSocket
201→        // AC: @trait-websocket-protocol ac-3 - Broadcast event
202→        pubsub.broadcast('triage:updates', 'triage_record_created', {
203→          ulid: savedRecord._ulid,
204→          inbox_ref: savedRecord.inbox_ref,
205→          action: savedRecord.action,
206→        }, projectContext.path);
207→
208→        // AC: @trait-api-endpoint ac-1 - Return 2xx with JSON body
