210→          success: true,
211→          record: savedRecord,
212→        };
213→      },
214→      {
215→        body: t.Object({
216→          inbox_ref: t.String(),
217→          action: t.String(),
218→          reasoning: t.String(),
219→          decided_by: t.Optional(t.String()),
220→          evidence_refs: t.Optional(t.Array(t.String())),
221→        }),
222→      }
