  --design-status-cancelled: oklch(0.704 0.04 256);
  --design-status-cancelled-fg: oklch(0.985 0.003 247);

  /* ── Severity Colors (4) ── */
  --design-severity-error: oklch(0.704 0.191 22.2);
  --design-severity-error-fg: oklch(0.985 0.003 247);
  --design-severity-error-muted: oklch(0.25 0.06 22);
  --design-severity-error-muted-fg: oklch(0.78 0.12 22);
  --design-severity-error-border: oklch(0.4 0.1 22);
  --design-severity-warning: oklch(0.828 0.189 84.4);
  --design-severity-warning-fg: oklch(0.21 0.034 46);
  --design-severity-warning-muted: oklch(0.25 0.06 80);
