  --design-severity-warning-border: oklch(0.4 0.1 80);
  --design-severity-info: oklch(0.488 0.243 264.4);
  --design-severity-info-fg: oklch(0.985 0.003 247);
  --design-severity-info-muted: oklch(0.22 0.06 264);
