  6→ * First click shows confirmation state, second click within 3s triggers the action.
  7→ * Auto-resets after 3s if not confirmed.
  8→ */
  9→import { cn } from '$lib/utils.js';
 10→
 11→interface Props {
 12→  /** Initial button label */
 13→  label: string;
 14→  /** Label shown during confirmation state */
 15→  confirmLabel?: string;
 16→  /** Visual variant */
 17→  variant?: 'destructive' | 'warning';
 18→  /** Whether the button is disabled */
 19→  disabled?: boolean;
 20→  /** Callback when action is confirmed */
 21→  onConfirm: () => void | Promise<void>;
 22→  /** Additional CSS classes */
 23→  class?: string;
 24→  /** Test ID for E2E testing */
 25→  testId?: string;
 26→}
 27→
 28→const {
 29→  label,
 30→  confirmLabel = 'Confirm?',
 31→  variant = 'destructive',
 32→  disabled = false,
 33→  onConfirm,
 34→  class: className,
 35→  testId,
 36→}: Props = $props();
 37→
 38→let confirming = $state(false);
 39→let timeoutId = $state<ReturnType<typeof setTimeout> | null>(null);
 40→
 41→function clearResetTimeout() {
 42→  if (timeoutId) {
 43→    clearTimeout(timeoutId);
 44→    timeoutId = null;
 45→  }
 46→}
 47→
 48→function resetState() {
 49→  confirming = false;
