 56→  if (confirming) {
 57→    // Second click - confirm the action
 58→    resetState();
 59→    await onConfirm();
 60→  } else {
 61→    // First click - enter confirmation state
 62→    confirming = true;
 63→    // Auto-reset after 3 seconds
 64→    timeoutId = setTimeout(() => {
 65→      confirming = false;
 66→      timeoutId = null;
 67→    }, 3000);
 68→  }
 69→}
 70→
 71→// Cleanup on unmount
 72→$effect(() => {
 73→  return () => {
 74→    clearResetTimeout();
 75→  };
 76→});
