 83→      ? 'bg-red-700 text-white hover:bg-red-800'
 84→      : 'bg-red-600 text-white hover:bg-red-700'
 85→    : confirming
 86→      ? 'bg-amber-700 text-white hover:bg-amber-800'
 87→      : 'bg-amber-600 text-white hover:bg-amber-700',
 88→);
 89→
 90→const disabledClasses = 'opacity-50 cursor-not-allowed';
 91→</script>
 92→
 93→<button
 94→  type="button"
 95→  class={cn(baseClasses, variantClasses, disabled && disabledClasses, className)}
 96→  onclick={handleClick}
 97→  {disabled}
 98→  data-testid={testId}
 99→>
