     9→import type { UnifiedSpoke } from '$lib/state/spokes.svelte.js';
    10→import { cn } from '$lib/utils.js';
    11→import InlineConfirmButton from './InlineConfirmButton.svelte';
    12→
    13→interface Props {
    14→  /** The spoke this menu is for */
    15→  spoke: UnifiedSpoke;
    16→  /** Whether the menu is open */
    17→  open?: boolean;
    18→  /** Callback when open state changes */
    19→  onOpenChange?: (open: boolean) => void;
    20→  /** Callback for rename action */
    21→  onRename: () => void;
    22→  /** Callback for pause action */
    23→  onPause: () => Promise<void>;
    24→  /** Callback for resume action */
    25→  onResume: () => Promise<void>;
    26→  /** Callback for view details action */
    27→  onViewDetails: () => void;
    28→  /** Callback for revoke action */
    29→  onRevoke: () => Promise<void>;
    30→  /** Children to render (typically SpokeCard) */
    31→  children: import('svelte').Snippet;
    32→}
    33→
    34→const {
    35→  spoke,
    36→  open = false,
    37→  onOpenChange,
    38→  onRename,
    39→  onPause,
    40→  onResume,
    41→  onViewDetails,
    42→  onRevoke,
    43→  children,
    44→}: Props = $props();
    45→
    46→// Track loading states
    47→let pauseLoading = $state(false);
    48→let resumeLoading = $state(false);
    49→let revokeLoading = $state(false);
    50→
    51→const isPaused = $derived(spoke.enrollmentStatus === 'paused');
    52→const isRevoked = $derived(spoke.enrollmentStatus === 'revoked');
    53→
    54→function closeMenu() {
    55→  onOpenChange?.(false);
    56→}
    57→
    58→async function handlePause() {
    59→  pauseLoading = true;
    60→  try {
    61→    await onPause();
    62→    closeMenu();
    63→  } finally {
    64→    pauseLoading = false;
    65→  }
    66→}
    67→
    68→async function handleResume() {
    69→  resumeLoading = true;
    70→  try {
    71→    await onResume();
    72→    closeMenu();
    73→  } finally {
    74→    resumeLoading = false;
    75→  }
    76→}
    77→
    78→async function handleRevoke() {
    79→  revokeLoading = true;
    80→  try {
    81→    await onRevoke();
    82→    closeMenu();
    83→  } finally {
    84→    revokeLoading = false;
    85→  }
    86→}
    87→
    88→function handleRename() {
    89→  onRename();
    90→  closeMenu();
    91→}
    92→
    93→function handleViewDetails() {
    94→  onViewDetails();
    95→  closeMenu();
    96→}
    97→
    98→/**
    99→ * Handle click outside to close menu.
   100→ */
   101→function handleClickOutside(event: MouseEvent) {
   102→  const target = event.target as HTMLElement;
   103→  if (!target.closest('.spoke-actions-menu')) {
   104→    closeMenu();
   105→  }
   106→}
   107→
   108→/**
   109→ * Handle escape key to close menu.
   110→ */
   111→function handleKeyDown(event: KeyboardEvent) {
   112→  if (event.key === 'Escape') {
   113→    closeMenu();
   114→  }
   115→}
   116→
   117→const menuItemClasses =
   118→  'flex w-full items-center gap-2 rounded px-3 py-2 text-sm outline-none transition-colors hover:bg-zinc-800 focus:bg-zinc-800 cursor-pointer text-left';
   119→const menuItemDisabledClasses = 'opacity-50 cursor-not-allowed hover:bg-transparent';
   120→</script>
   121→
   122→<svelte:window onclick={open ? handleClickOutside : undefined} onkeydown={open ? handleKeyDown : undefined} />
   123→
   124→<div class="spoke-actions-menu relative">
   125→  {@render children()}
   126→
   127→  {#if open}
   128→    <div
   129→      class="absolute right-0 top-full z-50 mt-1 min-w-[180px] rounded-lg border border-zinc-800 bg-zinc-900 p-1 shadow-xl"
   130→      role="menu"
   131→    >
   132→      <!-- Rename -->
   133→      <button
   134→        type="button"
   135→        class={cn(menuItemClasses, isRevoked && menuItemDisabledClasses)}
   136→        disabled={isRevoked}
   137→        onclick={handleRename}
   138→        role="menuitem"
   139→      >
   140→        <Edit class="h-4 w-4 text-zinc-400" />
   141→        <span class="text-zinc-200">Rename</span>
   142→      </button>
   143→
   144→      <!-- Pause/Resume -->
   145→      {#if isPaused}
   146→        <button
   147→          type="button"
   148→          class={cn(menuItemClasses, (resumeLoading || isRevoked) && menuItemDisabledClasses)}
   149→          disabled={resumeLoading || isRevoked}
   150→          onclick={handleResume}
   151→          role="menuitem"
   152→        >
   153→          <Play class="h-4 w-4 text-emerald-400" />
   154→          <span class="text-zinc-200">{resumeLoading ? 'Resuming...' : 'Resume'}</span>
   155→        </button>
   156→      {:else}
   157→        <!-- Pause needs inline confirmation -->
   158→        <div class="px-1 py-0.5">
   159→          <InlineConfirmButton
   160→            label="Pause"
   161→            confirmLabel="Confirm pause?"
   162→            variant="warning"
   163→            disabled={pauseLoading || isRevoked}
   164→            onConfirm={handlePause}
   165→            class="flex w-full items-center gap-2 rounded px-2 py-2 text-sm"
   166→          />
   167→        </div>
   168→      {/if}
   169→
   170→      <div class="my-1 h-px bg-zinc-800" role="separator"></div>
   171→
   172→      <!-- View Details -->
   173→      <button
   174→        type="button"
   175→        class={menuItemClasses}
   176→        onclick={handleViewDetails}
   177→        role="menuitem"
   178→      >
   179→        <Eye class="h-4 w-4 text-zinc-400" />
   180→        <span class="text-zinc-200">View Details</span>
   181→      </button>
   182→
   183→      <div class="my-1 h-px bg-zinc-800" role="separator"></div>
   184→
   185→      <!-- Revoke -->
   186→      <div class="px-1 py-0.5">
   187→        <InlineConfirmButton
   188→          label="Revoke"
   189→          confirmLabel="Confirm revoke?"
   190→          variant="destructive"
   191→          disabled={revokeLoading || isRevoked}
   192→          onConfirm={handleRevoke}
   193→          class="flex w-full items-center gap-2 rounded px-2 py-2 text-sm"
   194→        />
   195→      </div>
   196→    </div>
   197→  {/if}
   198→</div>
