              if (status.generatedAt) {
                console.log(chalk.gray(`  Generated: ${status.generatedAt}`));
              }
              break;
          }
        });
      } catch (err) {
        error("Failed to check agent status", err);
        process.exit(EXIT_CODES.ERROR);
      }
    });
