 487→              const elapsed = Math.round(inv.elapsedMs / 1000);
 488→              const taskStr = inv.taskRef ? `  task: ${chalk.yellow(inv.taskRef)}` : "";
 489→              console.log(`  ${chalk.cyan(inv.agentId)}  ${chalk.gray(inv.agentName)}`);
 490→              console.log(`    session: ${chalk.gray(inv.sessionId)}  elapsed: ${elapsed}s${taskStr}`);
 491→            }
 492→          }
 493→
 494→          const queuedItems = data.queued ?? [];
 495→          if (queuedItems.length > 0) {
 496→            console.log();
 497→            console.log(chalk.bold("Queued:"));
 498→            for (const q of queuedItems) {
 499→              const wait = Math.round(q.waitMs / 1000);
 500→              const taskStr = q.taskRef ? `  task: ${chalk.yellow(q.taskRef)}` : "";
 501→              console.log(`  ${chalk.cyan(q.agentId)}  ${chalk.gray(q.agentName)}`);
 502→              console.log(`    waiting: ${wait}s${taskStr}`);
 503→            }
 504→          }
 505→        });
 506→      } catch (err) {
 507→        error("Failed to get agent status", err);
 508→        process.exit(EXIT_CODES.ERROR);
 509→      }
 510→    });
 511→
 512→  // ─── kspec agent dispatch ─────────────────────────────────────────────────
 513→
 514→  const dispatch = agent
 515→    .command("dispatch")
 516→    .description("Manage the agent dispatch engine");
 517→
 518→  // AC: @cli-agent-commands ac-4
 519→  // AC: @cli-agent-commands ac-10
 520→  dispatch
 521→    .command("start")
 522→    .description("Start the dispatch engine (daemon must be running)")
 523→    .option("--json", "Output as JSON")
 524→    .action(async (opts) => {
 525→      try {
 526→        const daemonConn = getDaemonUrl();
 527→
 528→        // AC: @cli-agent-commands ac-10 - error when daemon not running
 529→        if (!daemonConn) {
 530→          error(
 531→            "Daemon is not running. The dispatch engine requires the daemon.",
 532→            { suggestion: "Start the daemon first with: kspec serve" },
 533→          );
 534→          process.exit(EXIT_CODES.ERROR);
 535→        }
 536→
 537→        const ctx = await initContext();
 538→
 539→        const headers: Record<string, string> = {
 540→          "Content-Type": "application/json",
 541→        };
 542→        if (ctx.rootDir) {
 543→          headers["X-Kspec-Dir"] = ctx.rootDir;
 544→        }
 545→
 546→        const response = await fetch(`${daemonConn.url}/api/agent/dispatch/start`, {
 547→          method: "POST",
 548→          headers,
 549→        });
 550→
 551→        if (!response.ok) {
 552→          const body = await response.text();
 553→          error(`Failed to start dispatch engine: ${response.status} - ${body}`);
 554→          process.exit(EXIT_CODES.ERROR);
 555→        }
 556→
 557→        const data = await response.json() as {
 558→          started: boolean;
 559→          reason?: string;
 560→          status?: { running: boolean; activeInvocations: number; queuedInvocations: number };
 561→        };
 562→
 563→        output(data, () => {
 564→          if (data.started) {
 565→            success("Dispatch engine started");
 566→          } else {
 567→            console.log(chalk.yellow(`Dispatch engine: ${data.reason ?? "already running"}`));
 568→          }
 569→        });
 570→      } catch (err) {
 571→        error("Failed to start dispatch engine", err);
 572→        process.exit(EXIT_CODES.ERROR);
 573→      }
 574→    });
 575→
 576→  // AC: @cli-agent-commands ac-5
 577→  dispatch
 578→    .command("stop")
 579→    .description("Stop the dispatch engine gracefully")
 580→    .option("--json", "Output as JSON")
 581→    .action(async (opts) => {
 582→      try {
 583→        const daemonConn = getDaemonUrl();
 584→
 585→        if (!daemonConn) {
 586→          error(
 587→            "Daemon is not running.",
 588→            { suggestion: "Start the daemon with: kspec serve" },
 589→          );
 590→          process.exit(EXIT_CODES.ERROR);
 591→        }
 592→
 593→        const ctx = await initContext();
 594→
 595→        const headers: Record<string, string> = {
 596→          "Content-Type": "application/json",
 597→        };
 598→        if (ctx.rootDir) {
 599→          headers["X-Kspec-Dir"] = ctx.rootDir;
 600→        }
 601→
 602→        const response = await fetch(`${daemonConn.url}/api/agent/dispatch/stop`, {
 603→          method: "POST",
 604→          headers,
 605→        });
 606→
 607→        if (!response.ok) {
 608→          const body = await response.text();
 609→          error(`Failed to stop dispatch engine: ${response.status} - ${body}`);
 610→          process.exit(EXIT_CODES.ERROR);
 611→        }
 612→
 613→        const data = await response.json() as { stopped: boolean; reason?: string };
 614→
 615→        output(data, () => {
 616→          if (data.stopped) {
 617→            success("Dispatch engine stopped");
 618→          } else {
 619→            console.log(chalk.yellow(`Dispatch engine: ${data.reason ?? "not running"}`));
 620→          }
 621→        });
 622→      } catch (err) {
 623→        error("Failed to stop dispatch engine", err);
 624→        process.exit(EXIT_CODES.ERROR);
 625→      }
 626→    });
 627→
 628→  // AC: @cli-agent-commands ac-9
 629→  dispatch
 630→    .command("status")
 631→    .description("Show dispatch engine status and loaded agents")
 632→    .option("--json", "Output as JSON")
 633→    .action(async (opts) => {
 634→      try {
 635→        const daemonConn = getDaemonUrl();
 636→
 637→        if (!daemonConn) {
 638→          // Daemon not running — show as disabled
 639→          output(
 640→            { running: false, activeInvocations: 0, queuedInvocations: 0, agents: [] },
 641→            () => {
 642→              console.log(chalk.bold("Dispatch Status"));
 643→              console.log();
 644→              console.log(`  Dispatch engine: ${chalk.gray("not available (daemon offline)")}`);
 645→              console.log(chalk.gray("  Start daemon with: kspec serve"));
 646→            },
 647→          );
 648→          return;
 649→        }
 650→
 651→        const ctx = await initContext();
 652→
 653→        const headers: Record<string, string> = {};
 654→        if (ctx.rootDir) {
 655→          headers["X-Kspec-Dir"] = ctx.rootDir;
 656→        }
 657→
 658→        // Get dispatch status
 659→        const statusResponse = await fetch(`${daemonConn.url}/api/agent/dispatch/status`, { headers });
 660→        if (!statusResponse.ok) {
 661→          error(`Daemon returned error: ${statusResponse.status}`);
 662→          process.exit(EXIT_CODES.ERROR);
 663→        }
 664→
 665→        const statusData = await statusResponse.json() as {
 666→          running: boolean;
 667→          activeInvocations: number;
 668→          queuedInvocations: number;
 669→        };
 670→
 671→        // Get loaded agents
 672→        let agents: Array<{ id: string; name: string }> = [];
 673→        try {
 674→          const meta = await loadMetaContext(ctx);
 675→          agents = meta.agents.map((a) => ({ id: a.id, name: a.name }));
 676→        } catch {
 677→          // Meta may not be available
 678→        }
 679→
 680→        const fullData = { ...statusData, agents };
 681→
 682→        output(fullData, () => {
 683→          console.log(chalk.bold("Dispatch Status"));
 684→          console.log();
 685→          console.log(`  Engine:             ${statusData.running ? chalk.green("enabled") : chalk.yellow("disabled")}`);
 686→          console.log(`  Active invocations: ${chalk.cyan(String(statusData.activeInvocations))}`);
 687→          console.log(`  Queued invocations: ${chalk.cyan(String(statusData.queuedInvocations))}`);
 688→          console.log();
 689→          console.log(chalk.bold("Loaded Agents:"));
 690→          if (agents.length === 0) {
 691→            console.log(chalk.gray("  (none defined)"));
 692→          } else {
 693→            for (const a of agents) {
 694→              console.log(`  ${chalk.cyan(a.id)}  ${chalk.gray(a.name)}`);
 695→            }
 696→          }
 697→        });
 698→      } catch (err) {
 699→        error("Failed to get dispatch status", err);
 700→        process.exit(EXIT_CODES.ERROR);
 701→      }
 702→    });
 703→
 704→  // ─── kspec agent dispatch watch ───────────────────────────────────────────
 705→
 706→  // AC: @cli-agent-commands ac-13 through ac-18
 707→  dispatch
 708→    .command("watch")
 709→    .description("Stream agent text output from the dispatch engine in real time")
 710→    .option("--agent <name>", "Only show output from this agent")
 711→    .option("--session <id>", "Only show output from this session")
 712→    .option("--retries <n>", "Number of reconnect attempts on disconnect (default 5)", "5")
 713→    .action(async (opts) => {
 714→      const DEFAULT_RETRIES = 5;
 715→      const RETRY_BASE_MS = 1000;
 716→      const MAX_RETRY_MS = 30_000;
 717→
 718→      // AC: @cli-agent-commands ac-15 — error when daemon not running
 719→      const daemonConn = getDaemonUrl();
 720→      if (!daemonConn) {
 721→        error(
 722→          "Daemon is not running. The watch command requires the daemon.",
 723→        );
 724→        info("Suggestion: Start the daemon with: kspec serve");
 725→        // AC: @cli-agent-commands ac-15 — exit code 3
 726→        process.exit(EXIT_CODES.NOT_FOUND);
 727→        return;
 728→      }
 729→
 730→      const parsedRetries = parseIntOption(opts.retries, {
 731→        min: 0,
 732→        max: Number.MAX_SAFE_INTEGER,
 733→        name: "Retries",
 734→      });
 735→      if (!parsedRetries.ok) {
 736→        error(`Invalid --retries value: ${parsedRetries.error}`, {
 737→          suggestion: "Example: --retries 5",
 738→        });
 739→        process.exit(EXIT_CODES.VALIDATION_FAILED);
 740→        return;
 741→      }
 742→      const retryLimit = parsedRetries.value;
 743→      const agentFilter: string | undefined = opts.agent;
 744→      const sessionFilter: string | undefined = opts.session;
 745→      type StreamRenderState = {
 746→        hasRenderedBody: boolean;
 747→        spacerPending: boolean;
 748→      };
 749→      const streamStates = new Map<string, StreamRenderState>();
 750→      let activeStreamKey: string | null = null;
 751→      let outputAtLineStart = true;
 752→
 753→      function getStreamState(streamKey: string): StreamRenderState {
 754→        let state = streamStates.get(streamKey);
 755→        if (!state) {
 756→          state = { hasRenderedBody: false, spacerPending: false };
 757→          streamStates.set(streamKey, state);
 758→        }
 759→        return state;
 760→      }
 761→
 762→      function writeRaw(text: string): void {
 763→        if (!text) return;
 764→        process.stdout.write(text);
 765→        outputAtLineStart = text.endsWith("\n");
 766→      }
 767→
 768→      function writeSpeakerText(text: string): void {
 769→        if (!text) return;
 770→
 771→        writeRaw(text);
 772→      }
 773→
 774→      function ensureLineBreak(): void {
 775→        if (!outputAtLineStart) {
 776→          writeRaw("\n");
 777→        }
 778→      }
 779→
 780→      function startSpeakerSection(streamKey: string, prefix: string): void {
 781→        if (activeStreamKey === streamKey) return;
 782→        if (activeStreamKey) {
 783→          ensureLineBreak();
 784→        }
 785→        writeRaw(`${prefix}\n`);
 786→        activeStreamKey = streamKey;
 787→      }
 788→
 789→      function queuePrefixedChunk(
 790→        streamKey: string,
 791→        prefix: string,
 792→        text: string,
 793→      ): void {
 794→        if (!text) return;
 795→        const switchingSpeaker = activeStreamKey !== null && activeStreamKey !== streamKey;
 796→        startSpeakerSection(streamKey, prefix);
 797→        const state = getStreamState(streamKey);
 798→        if (switchingSpeaker) {
 799→          // Marker change already separates context; don't carry stale spacer
 800→          // into the top of a newly active speaker section.
 801→          state.spacerPending = false;
 802→        } else if (state.spacerPending && state.hasRenderedBody) {
 803→          ensureLineBreak();
 804→          writeRaw("\n");
 805→          state.spacerPending = false;
 806→        }
 807→        writeSpeakerText(text);
 808→        state.hasRenderedBody = true;
 809→      }
 810→
 811→      function markMessageBoundary(streamKey: string): void {
 812→        // Boundary signals are stream-local; ignore inactive streams.
 813→        if (activeStreamKey !== streamKey) return;
 814→        const state = getStreamState(streamKey);
 815→        ensureLineBreak();
 816→        // Coalesce repeated boundary events into one pending spacer.
 817→        if (state.hasRenderedBody) {
 818→          state.spacerPending = true;
 819→        }
 820→      }
 821→
 822→      function formatSessionIdForDisplay(sessionId: string): string {
 823→        // AC: @cli-agent-commands ac-17 — shorten session ULID in watch prefix.
 824→        return sessionId ? sessionId.slice(0, 8) : "";
 825→      }
 826→
 827→      // Resolve project dir for WebSocket project binding
 828→      let projectDir: string | undefined;
 829→      try {
 830→        const ctx = await initContext();
 831→        projectDir = ctx.rootDir;
 832→      } catch {
 833→        // non-fatal: WebSocket will use daemon default
 834→      }
 835→
 836→      let retryCount = 0;
 837→      let shouldReconnect = true;
 838→
 839→      function connect(): void {
 840→        const wsUrl = new URL(`ws://localhost:${daemonConn!.port}/ws`);
 841→        if (projectDir) {
 842→          wsUrl.searchParams.set("project", projectDir);
 843→        }
 844→
 845→        // AC: @cli-agent-commands ac-15 — Node 22+ has global WebSocket
 846→        const ws = new WebSocket(wsUrl.toString());
 847→
 848→        ws.onopen = () => {
 849→          retryCount = 0;
 850→          // Subscribe to agents topic
 851→          ws.send(JSON.stringify({
 852→            action: "subscribe",
 853→            request_id: "watch-subscribe",
 854→            payload: { topics: ["agents"] },
 855→          }));
 856→        };
 857→
 858→        ws.onmessage = (event: MessageEvent) => {
 859→          let msg: Record<string, unknown>;
 860→          try {
 861→            msg = JSON.parse(event.data as string);
 862→          } catch {
 863→            return;
 864→          }
 865→
 866→          // AC: @cli-agent-commands ac-18 — fail fast on subscribe handshake rejection.
 867→          if (msg.ack === true && msg.request_id === "watch-subscribe") {
 868→            if (msg.success === false) {
 869→              shouldReconnect = false;
 870→              const reasonParts = [msg.error, msg.details]
 871→                .filter((value): value is string => typeof value === "string" && value.length > 0);
 872→              const reason = reasonParts.length > 0 ? ` (${reasonParts.join(": ")})` : "";
 873→              if (activeStreamKey) {
 874→                ensureLineBreak();
 875→              }
 876→              error(`Failed to subscribe to daemon agent output stream${reason}.`);
 877→              info("Suggestion: Verify daemon logs for subscribe errors, then restart with: kspec serve");
 878→              process.exit(EXIT_CODES.NOT_FOUND);
 879→            }
 880→            return;
 881→          }
 882→
 883→          // AC: @cli-agent-commands ac-13 — stream text with per-line [agent-id session-id] prefixes
 884→          if (msg.event === "agent_text_chunk" && msg.data) {
 885→            const data = msg.data as {
 886→              session_id?: string;
 887→              agent_id?: string;
 888→              text?: string;
 889→            };
 890→            const sessionId = data.session_id ?? "";
 891→            const agentId = data.agent_id ?? "";
 892→            const text = data.text ?? "";
 893→
 894→            // AC: @cli-agent-commands ac-16 — filter by agent/session if specified
 895→            if (agentFilter && agentId !== agentFilter) return;
 896→            if (sessionFilter && sessionId !== sessionFilter) return;
 897→
 898→            const streamKey = `${agentId}\u0000${sessionId}`;
 899→            const displaySessionId = formatSessionIdForDisplay(sessionId);
 900→            const prefix = `[${agentId} ${displaySessionId}]`;
 901→            // Match old Ralph rendering semantics: empty chunk marks message end.
 902→            if (text.length === 0) {
 903→              markMessageBoundary(streamKey);
 904→              return;
 905→            }
 906→            queuePrefixedChunk(streamKey, prefix, text);
 907→          }
 908→        };
 909→
 910→        ws.onerror = () => {
 911→          // error event fires before close, handled in onclose
 912→        };
 913→
 914→        ws.onclose = () => {
 915→          if (!shouldReconnect) return;
 916→
 917→          if (activeStreamKey) {
 918→            ensureLineBreak();
 919→          }
 920→
 921→          if (retryCount >= retryLimit) {
 922→            // AC: @cli-agent-commands ac-14 — exit code 3 when retries exhausted
 923→            error(
 924→              `WebSocket connection lost and reconnection failed after ${retryLimit} attempt(s).`,
 925→            );
 926→            info("Suggestion: Verify the daemon is still running with: kspec serve");
 927→            process.exit(EXIT_CODES.NOT_FOUND);
 928→            return;
 929→          }
 930→
 931→          retryCount++;
 932→          const backoffMs = Math.min(
 933→            RETRY_BASE_MS * Math.pow(2, retryCount - 1),
 934→            MAX_RETRY_MS,
 935→          );
 936→          // AC: @cli-agent-commands ac-14 — print reconnecting message
 937→          process.stderr.write(
 938→            `[watch] Connection lost. Reconnecting in ${Math.round(backoffMs / 1000)}s (attempt ${retryCount}/${retryLimit})...\n`,
 939→          );
 940→          setTimeout(connect, backoffMs);
 941→        };
 942→      }
 943→
 944→      connect();
 945→
 946→      // Keep process alive (WebSocket is non-blocking in Node)
 947→      // Users interrupt with Ctrl+C
 948→      await new Promise<void>(() => {/* intentionally never resolves */});
 949→    });
 950→
 951→  // ─── kspec agent end-loop ─────────────────────────────────────────────────
 952→
 953→  // AC: @ralph-replacement ac-1 — equivalent to kspec ralph end-loop
 954→  // AC: @session-end-loop-signal ac-signal
 955→  agent
 956→    .command("end-loop")
 957→    .description("Signal the agent dispatch engine to stop after current iteration")
 958→    .option("--reason <reason>", "Reason for ending the loop")
 959→    .action(async (options) => {
 960→      try {
 961→        const ctx = await initContext();
 962→        const sessionId = process.env.KSPEC_SESSION_ID;
 963→
 964→        if (!sessionId) {
 965→          // AC: @trait-error-guidance ac-1, ac-2
 966→          warn("No active agent session detected (KSPEC_SESSION_ID not set).");
 967→          info(
 968→            "This command requires an active session. It is designed to be called by agents during a dispatch invocation.",
 969→          );
 970→          info(
 971→            "Suggestion: Ensure KSPEC_SESSION_ID is set, or start a session with: kspec session create",
 972→          );
 973→          process.exit(EXIT_CODES.VALIDATION_FAILED);
 974→          return;
 975→        }
 976→
 977→        // Write end-loop state to session
 978→        const updated = await requestEndLoop(
 979→          ctx.specDir,
 980→          sessionId,
 981→          options.reason,
 982→        );
 983→
 984→        if (!updated) {
 985→          // AC: @trait-error-guidance ac-1, ac-2
 986→          error(`Session not found: ${sessionId}`);
 987→          info("Suggestion: Check session ID with: kspec session log list");
 988→          process.exit(EXIT_CODES.NOT_FOUND);
 989→          return;
 990→        }
 991→
 992→        success("Loop end signal sent");
 993→        if (options.reason) {
 994→          info(`Reason: ${options.reason}`);
 995→        }
 996→      } catch (err) {
 997→        // AC: @trait-error-guidance ac-1
 998→        error("Failed to signal end-loop", err);
 999→        process.exit(EXIT_CODES.ERROR);
1000→      }
1001→    });
1002→}
