      // Error should be displayed
      const errorEl = dialog.getByTestId('agent-edit-error');
      await expect(errorEl).toBeVisible();
      await expect(errorEl).toContainText('Save failed');

      // Dialog should remain open
      await expect(dialog).toBeVisible();
    });

    // AC: @ui-agent-dispatch ac-4
    test('can add and remove dispatch triggers', async ({ page, daemon }) => {
      await page.goto('/agents');
      await expect(page.getByTestId('agents-loading')).toHaveCount(0);

      // Use pr-reviewer which has only 1 trigger
      const card = page.getByTestId('agent-card-pr-reviewer');
      await card.getByTestId('agent-edit-button').click();

      const dialog = page.getByTestId('agent-edit-dialog');
      await expect(dialog).toBeVisible();

      // Should start with 1 trigger
      let triggerRows = dialog.getByTestId('agent-edit-trigger-row');
      await expect(triggerRows).toHaveCount(1);

      // Add a trigger
      await dialog.getByTestId('agent-edit-add-trigger').click();
      triggerRows = dialog.getByTestId('agent-edit-trigger-row');
      await expect(triggerRows).toHaveCount(2);

      // Remove the first trigger
      const removeButtons = dialog.getByTestId('agent-edit-remove-trigger');
      await removeButtons.first().click();
      triggerRows = dialog.getByTestId('agent-edit-trigger-row');
      await expect(triggerRows).toHaveCount(1);
    });

    // AC: @ui-agent-dispatch ac-4
    test('prompt template field is editable', async ({ page, daemon }) => {
      await page.goto('/agents');
      await expect(page.getByTestId('agents-loading')).toHaveCount(0);

      const card = page.getByTestId('agent-card-task-worker');
      await card.getByTestId('agent-edit-button').click();

      const dialog = page.getByTestId('agent-edit-dialog');
      const promptField = dialog.getByTestId('agent-edit-prompt-template');
      await expect(promptField).toBeVisible();

      // Type a prompt template
      await promptField.fill('You are a task worker agent.');
      await expect(promptField).toHaveValue('You are a task worker agent.');
    });
  });
});

