  await nameInput.fill('Updated Worker');

  await dialog.getByTestId('agent-edit-save').click();
  await expect(dialog).not.toBeVisible();

  // Verify via API that the change was persisted
  const response = await request.get(`${DAEMON_URL}/api/meta/agents`);
  const body = await response.json();
  const agent = body.items.find((a: { id: string }) => a.id === 'task-worker');
  expect(agent.name).toBe('Updated Worker');
});

